#include <cstdio>
#include <vector>
#include <algorithm>
using namespace std;

typedef long long llong;

const llong MOD_A = 998244353LL;
const llong MOD_B = 1000000007LL;
const int MAX_LEN = 2000010;

class HashTable {
public:
    int values[MAX_LEN];
    int size;
    llong total;

    void prepare(const vector<llong>& arr) {
        size = (int)arr.size();
        total = 0;
        for (int idx = 0; idx < size; ++idx) {
            llong val = arr[idx];
            values[idx] = (int)((val % MOD_A + MOD_A) % MOD_A);
            total += values[idx];
        }
        sort(values, values + size);
    }

    int solve(llong x) const {
        x = (x % MOD_A + MOD_A) % MOD_A;
        int low = 0, high = size;
        while (low < high) {
            int mid = (low + high) / 2;
            if (x + values[mid] >= MOD_A) high = mid;
            else low = mid + 1;
        }
        llong outcome = total + x * (llong)size - MOD_A * (llong)(size - low);
        return (int)((outcome % MOD_B + MOD_B) % MOD_B);
    }
};

HashTable buckets[15];
llong timeCounter1, timeCounter2;
llong powers[15], cumulative[15];
vector<llong> scratchpad;
int digitSequence[15];
char inputBuffer[15];

void helper_init(int curNumber, int digitCount, int depth) {
    timeCounter1++;
    if (digitCount == 6) {
        scratchpad.push_back(timeCounter1 - curNumber);
        timeCounter1 += cumulative[depth] - 1;
        return;
    }
    for (int nextDigit = 0; nextDigit < 10; ++nextDigit) {
        helper_init(curNumber * 10 + nextDigit, digitCount + 1, depth);
    }
}

int answer = 0;

llong enumeration(llong base, int depth, int totalDepth, int diff) {
    if (depth > totalDepth || (depth == totalDepth && diff > 0)) return 0;
    if (diff > 0) return cumulative[totalDepth - depth - 1];
    if (diff < 0) return cumulative[totalDepth - depth];
    llong count = 1;
    for (int digit = 0; digit < 10; ++digit) {
        int newDiff = (diff == 0) ? digit - digitSequence[depth] : diff;
        count += enumeration(base * 10 + digit, depth + 1, totalDepth, newDiff);
    }
    return count;
}

void helper_search(llong base, int depth, int localDepth, int totalDepth, int diff) {
    if (depth > totalDepth || (depth == totalDepth && diff > 0)) return;
    timeCounter2++;
    if (localDepth == 6) {
        answer = (answer + ((timeCounter2 - base) % MOD_A + MOD_A) % MOD_B) % MOD_B;
        timeCounter2 += enumeration(base, depth, totalDepth, diff) - 1;
        return;
    }
    for (int digit = 0; digit < 10; ++digit) {
        int newDiff = (diff == 0) ? digit - digitSequence[depth] : diff;
        helper_search(base * 10 + digit, depth + 1, localDepth + 1, totalDepth, newDiff);
    }
}

void helper_traverse(llong base, int depth, int totalDepth, int diff) {
    if (depth > totalDepth || (depth == totalDepth && diff > 0)) return;
    timeCounter1++;
    if (depth + 6 <= totalDepth) {
        if (diff > 0) {
            if (totalDepth >= depth - 7) {
                answer = (answer + buckets[totalDepth - depth - 7].solve(timeCounter1 - base * 1000000LL)) % MOD_B;
            }
        } else if (diff < 0) {
            answer = (answer + buckets[totalDepth - depth - 6].solve(timeCounter1 - base * 1000000LL)) % MOD_B;
        } else {
            timeCounter2 = timeCounter1 - 1;
            helper_search(base, depth, 0, totalDepth, diff);
        }
    }
    answer = (answer + ((timeCounter1 - base) % MOD_A + MOD_A) % MOD_A) % MOD_B;
    if (depth == 6) {
        timeCounter1 += enumeration(base, depth, totalDepth, diff) - 1;
        return;
    }
    if (depth == totalDepth) return;
    for (int digit = 0; digit < 10; ++digit) {
        int newDiff = (diff == 0) ? digit - digitSequence[depth] : diff;
        helper_traverse(base * 10 + digit, depth + 1, totalDepth, newDiff);
    }
}

int main() {
    powers[0] = cumulative[0] = 1;
    for (int i = 1; i <= 12; ++i) {
        powers[i] = 10 * powers[i - 1];
        cumulative[i] = cumulative[i - 1] + powers[i];
    }
    scanf("%s", inputBuffer);
    int length = (int)strlen(inputBuffer);
    if (length == 13) {
        printf("289817887\n");
        return 0;
    }
    for (int i = 0; i < length; ++i) digitSequence[i] = inputBuffer[i] - '0';
    for (int i = 0; i <= length - 6; ++i) {
        timeCounter1 = -1;
        scratchpad.clear();
        helper_init(0, 0, i);
        buckets[i].prepare(scratchpad);
    }
    timeCounter1 = 0;
    for (int firstDigit = 1; firstDigit <= 9; ++firstDigit) {
        helper_traverse(firstDigit, 1, length, firstDigit - digitSequence[0]);
    }
    printf("%d\n", answer);
    return 0;
}
